// 主题模式枚举
type ThemeMode = 'system' | 'light' | 'warm' | 'dark';

// 用户偏好设置
interface UserPreferences {
  // 是否启用主题切换动画
  enableTransitions: boolean;

  // 动画持续时间（毫秒）
  transitionDuration: number;

  // 是否自动跟随系统
  autoFollowSystem: boolean;

  // 预设主题变体
  themeVariant: 'default' | 'high-contrast' | 'color-blind-friendly';

  // 个性化设置
  personalization: {
    // 卡片圆角大小
    borderRadius: 'none' | 'small' | 'medium' | 'large';

    // 字体大小缩放
    fontSizeScale: number; // 0.8 - 1.5

    // 颜色饱和度调整
    colorSaturation: number; // 0.5 - 1.5
  };
}

// 自定义颜色覆盖
interface CustomColorOverrides {
  // 主要颜色覆盖
  primary?: string;

  // 次要颜色覆盖
  secondary?: string;

  // 背景颜色覆盖
  background?: string;

  // 强调色覆盖
  accent?: string;

  // 自定义CSS变量覆盖
  cssVariables?: Record<string, string>;
}

// 性能设置
interface PerformanceSettings {
  // 是否启用硬件加速
  enableHardwareAcceleration: boolean;

  // 主题切换防抖时间（毫秒）
  debounceDelay: number;

  // 是否预加载主题资源
  preloadThemeResources: boolean;
}
