```typescript
// 主题切换状态
type ThemeTransitionState =
  | 'idle'           // 空闲状态
  | 'preparing'      // 准备切换
  | 'switching'      // 正在切换
  | 'validating'     // 验证样式
  | 'completed'      // 切换完成
  | 'error';         // 发生错误

// 状态转换事件
type ThemeTransitionEvent =
  | { type: 'START_TRANSITION'; payload: { targetTheme: ThemeMode } }
  | { type: 'PREPARE_THEME'; payload: { styles: ComputedThemeStyles } }
  | { type: 'APPLY_THEME'; payload: { themeClass: string } }
  | { type: 'VALIDATE_STYLES'; payload: { contrastRatios: Record<string, number> } }
  | { type: 'COMPLETE_TRANSITION' }
  | { type: 'TRANSITION_ERROR'; payload: { error: ThemeError } };

// 状态转换函数
function transitionTheme(
  currentState: ThemeTransitionState,
  event: ThemeTransitionEvent
): ThemeTransitionState {
  switch (currentState) {
    case 'idle':
      return event.type === 'START_TRANSITION' ? 'preparing' : currentState;

    case 'preparing':
      return event.type === 'PREPARE_THEME' ? 'switching' : currentState;

    case 'switching':
      return event.type === 'APPLY_THEME' ? 'validating' : currentState;

    case 'validating':
      return event.type === 'VALIDATE_STYLES' ? 'completed' : currentState;

    case 'completed':
      return event.type === 'COMPLETE_TRANSITION' ? 'idle' : currentState;

    case 'error':
      return event.type === 'TRANSITION_ERROR' ? 'idle' : currentState;

    default:
      return currentState;
  }
}
```

