// __tests__/Accessibility.test.tsx
describe('Theme Accessibility', () => {
  it('should maintain WCAG AA contrast ratios', () => {
    const themes = ['light', 'warm', 'dark'];

    themes.forEach(theme => {
      // 应用主题
      document.documentElement.className = theme;

      // 检查对比度
      const bgColor = getComputedStyle(document.body)
        .backgroundColor;
      const textColor = getComputedStyle(document.body)
        .color;

      // 验证对比度 >= 4.5:1
      expect(getContrastRatio(bgColor, textColor)).toBeGreaterThanOrEqual(4.5);
    });
  });
});
