{"output":"// 主题管理工具
// 负责在前端即时切换浅色/深色/跟随系统模式

export type ThemeMode = 'system' | 'light' | 'dark'

interface ThemeState {
  mode: ThemeMode
  mediaQuery?: MediaQueryList
  listener?: (event: MediaQueryListEvent) => void
}

const state: ThemeState = {
  mode: 'system',
}

function applyThemeClass(theme: 'light' | 'dark') {
  const root = document.documentElement
  // 移除所有主题类
  root.classList.remove('dark')
  // 添加当前主题类（light模式不添加类，作为默认）
  if (theme === 'dark') {
    root.classList.add('dark')
  }
}

function cleanupListener() {
  if (state.mediaQuery && state.listener) {
    state.mediaQuery.removeEventListener('change', state.listener)
  }
  state.mediaQuery = undefined
  state.listener = undefined
}

export function applyTheme(mode: ThemeMode) {
  if (typeof window === 'undefined') return

  cleanupListener()
  state.mode = mode

  const updateFromSystem = (isDark: boolean) => {
    const effectiveTheme = isDark ? 'dark' : 'light'
    applyThemeClass(effectiveTheme)
    window.dispatchEvent(
      new CustomEvent('theme-changed', {
        detail: { mode, effective: effectiveTheme },
      }),
    )
  }

  if (mode === 'system') {
    const query = window.matchMedia('(prefers-color-scheme: dark)')
    updateFromSystem(query.matches)
    const listener = (event: MediaQueryListEvent) => updateFromSystem(event.matches)
    query.addEventListener('change', listener)
    state.mediaQuery = query
    state.listener = listener
  } else {
    applyThemeClass(mode)
    window.dispatchEvent(
      new CustomEvent('theme-changed', {
        detail: { mode, effective: mode },
      }),
    )
  }
}

export function getThemeMode(): ThemeMode {
  return state.mode
}

export function getEffectiveTheme(): 'light' | 'dark' {
  if (state.mode === 'system') {
    const query = window.matchMedia('(prefers-color-scheme: dark)')
    return query.matches ? 'dark' : 'light'
  }
  return state.mode
}

export function isDarkMode(): boolean {
  return getEffectiveTheme() === 'dark'
}

export function isLightMode(): boolean {
  return getEffectiveTheme() === 'light'
}
