{"output":"// 主题系统 Hook
// 实现支持 system/light/warm/dark 的主题切换，遵循 macOS HIG

import { useState, useEffect, useCallback, useRef } from 'react';
import type { Theme, UIConfig } from '../types';
import {
  systemThemeManager,
  onSystemThemeChange,
  type SystemThemeInfo,
  supportsSystemThemeDetection
} from '../utils/systemTheme';

export interface ThemeConfig {
  theme: Theme;
  effectiveTheme: 'light' | 'dark';
  isDarkMode: boolean;
  isWarmMode: boolean;
  isLightMode: boolean;
  systemPrefersDark: boolean;
}

// 主题 Hook
export function useTheme(config?: UIConfig) {
  const cleanupRef = useRef<(() => void) | null>(null);

  const [themeConfig, setThemeConfig] = useState<ThemeConfig>(() => {
    const initialTheme = config?.theme || 'system';
    const systemTheme = systemThemeManager.getCurrentTheme();

    console.log('[useTheme] Initializing with config:', config?.theme, 'systemTheme:', systemTheme);

    // 计算有效主题
    let effectiveTheme: 'light' | 'dark';
    if (initialTheme === 'system') {
      effectiveTheme = systemTheme === 'dark' ? 'dark' : 'light';
    } else {
      effectiveTheme = initialTheme as 'light' | 'dark';
    }

    const result = {
      theme: initialTheme,
      effectiveTheme,
      isDarkMode: effectiveTheme === 'dark',
      isWarmMode: effectiveTheme === 'light', // 浅色模式使用温暖配色
      isLightMode: effectiveTheme === 'light',
      systemPrefersDark: systemTheme === 'dark',
    };

    console.log('[useTheme] Initial theme config:', result);
    return result;
  });

  // 监听系统主题变化
  useEffect(() => {
    // 清理之前的监听器
    if (cleanupRef.current) {
      cleanupRef.current();
    }

    const handleSystemThemeChange = (systemTheme: 'light' | 'dark', _info: SystemThemeInfo) => {
      setThemeConfig(prev => {
        // 只有当设置为 'system' 时才响应系统主题变化
        if (prev.theme === 'system') {
          const newEffectiveTheme = systemTheme === 'dark' ? 'dark' : 'light';

          return {
            ...prev,
            systemPrefersDark: systemTheme === 'dark',
            effectiveTheme: newEffectiveTheme,
            isDarkMode: newEffectiveTheme === 'dark',
            isWarmMode: newEffectiveTheme === 'light', // 浅色模式使用温暖配色
            isLightMode: newEffectiveTheme === 'light',
          };
        }

        // 即使不是 system 模式，也要更新系统偏好状态
        return {
          ...prev,
          systemPrefersDark: systemTheme === 'dark',
        };
      });
    };

    // 添加系统主题监听器
    cleanupRef.current = onSystemThemeChange(handleSystemThemeChange);

    return () => {
      if (cleanupRef.current) {
        cleanupRef.current();
        cleanupRef.current = null;
      }
    };
  }, []);

  // 监听配置变化
  useEffect(() => {
    if (!config) {
      console.log('[useTheme] No config provided, skipping config update');
      return;
    }

    console.log('[useTheme] Config changed, new theme:', config.theme);

    setThemeConfig(prev => {
      if (prev.theme === config.theme) {
        console.log('[useTheme] Theme unchanged, skipping update');
        return prev;
      }

      const systemTheme = systemThemeManager.getCurrentTheme();
      let effectiveTheme: 'light' | 'dark';

      if (config.theme === 'system') {
        effectiveTheme = systemTheme === 'dark' ? 'dark' : 'light';
      } else {
        effectiveTheme = config.theme as 'light' | 'dark';
      }

      const newConfig = {
        ...prev,
        theme: config.theme,
        effectiveTheme,
        isDarkMode: effectiveTheme === 'dark',
        isWarmMode: effectiveTheme === 'light', // 浅色模式使用温暖配色
        isLightMode: effectiveTheme === 'light',
        systemPrefersDark: systemTheme === 'dark',
      };

      console.log('[useTheme] Updated theme config:', newConfig);
      return newConfig;
    });
  }, [config?.theme]);

  // 应用主题到DOM
  useEffect(() => {
    const root = document.documentElement;

    // 移除所有主题类
    root.classList.remove('dark');

    // 添加当前有效主题类（light模式不添加类，作为默认）
    if (themeConfig.effectiveTheme !== 'light') {
      root.classList.add(themeConfig.effectiveTheme);
    }

    // 设置meta theme-color
    const metaThemeColor = document.querySelector('meta[name="theme-color"]');
    if (metaThemeColor) {
      let themeColor = '#ffffff'; // light
      if (themeConfig.effectiveTheme === 'dark') {
        themeColor = '#1a1a1a';
      } else {
        themeColor = 'hsl(52, 94%, 94%)'; // cornsilk - 浅色模式使用温暖色
      }
      metaThemeColor.setAttribute('content', themeColor);
    }
  }, [themeConfig.effectiveTheme]);

  // 切换主题
  const setTheme = useCallback((theme: Theme) => {
    setThemeConfig(prev => {
      // 计算新的有效主题
      let effectiveTheme: 'light' | 'dark';
      if (theme === 'system') {
        const currentSystemTheme = systemThemeManager.getCurrentTheme();
        effectiveTheme = currentSystemTheme === 'dark' ? 'dark' : 'light';
      } else {
        effectiveTheme = theme as 'light' | 'dark';
      }

      return {
        theme,
        effectiveTheme,
        isDarkMode: effectiveTheme === 'dark',
        isWarmMode: effectiveTheme === 'light', // 浅色模式使用温暖配色
        isLightMode: effectiveTheme === 'light',
        systemPrefersDark: prev.systemPrefersDark,
      };
    });
  }, []);

  // 获取当前主题的CSS变量
  const getThemeVariables = useCallback(() => {
    const root = document.documentElement;
    const computedStyle = getComputedStyle(root);

    const variables: Record<string, string> = {};

    // 提取所有CSS变量
    for (let i = 0; i < computedStyle.length; i++) {
      const property = computedStyle[i];
      if (property.startsWith('--')) {
        variables[property] = computedStyle.getPropertyValue(property);
      }
    }

    return variables;
  }, []);

  // 获取当前主题信息
","metadata":{"exit_code":0,"duration_seconds":0.0}}

