}

// 主题颜色 Hook
export function useThemeColors() {
  const { isDarkMode, isLightMode } = useTheme();

  const colors = {
    // 背景色 - 浅色模式使用温暖的 Bright.scss 配色，深色模式保持原样
    background: isDarkMode ? '#1a1a1a' : 'hsl(52, 94%, 94%)',        // warm-cornsilk-200
    surface: isDarkMode ? '#2d2d2d' : 'hsl(67, 50%, 86%)',              // warm-beige-200
    surfaceSecondary: isDarkMode ? '#3a3a3a' : 'hsl(52, 94%, 96%)',        // warm-cornsilk-100
    surfaceTertiary: isDarkMode ? '#4a4a4a' : 'hsl(43, 82%, 92%)',           // warm-papaya-300

    // 文本色 - 浅色模式使用温暖的深色文字
    textPrimary: isDarkMode ? '#ffffff' : 'hsl(30, 53%, 15%)',          // warm-buff-900
    textSecondary: isDarkMode ? '#a1a1a6' : 'hsl(30, 53%, 35%)',         // warm-buff-700
    textTertiary: isDarkMode ? '#6e6e73' : 'hsl(74, 32%, 51%)',          // warm-tea-700
    textPlaceholder: isDarkMode ? '#48484a' : 'hsl(74, 32%, 61%)',        // warm-tea-600

    // 边框色 - 浅色模式使用温暖的边框
    border: isDarkMode ? '#38383a' : 'hsl(67, 50%, 81%)',              // warm-beige-300
    borderSecondary: isDarkMode ? '#48484a' : 'hsl(67, 50%, 86%)',         // warm-beige-200
    borderFocus: isDarkMode ? '#0a84ff' : 'hsl(30, 53%, 64%)',            // warm-buff-600

    // 状态色 (保持一致)
    success: isDarkMode ? '#30d158' : '#34c759',
    warning: isDarkMode ? '#ff9f0a' : '#ff9500',
    error: isDarkMode ? '#ff453a' : '#ff3b30',
    info: isDarkMode ? '#0a84ff' : '#007aff',

    // 交互色
    primary: isDarkMode ? '#0a84ff' : isLightMode ? 'hsl(30, 53%, 64%)' : '#007aff',
    primaryHover: isDarkMode ? '#409cff' : isLightMode ? 'hsl(30, 53%, 54%)' : '#0051d5',
    secondary: isDarkMode ? '#5856d6' : isLightMode ? 'hsl(74, 32%, 61%)' : '#5856d6',
    secondaryHover: isDarkMode ? '#6b69e9' : isLightMode ? 'hsl(74, 32%, 51%)' : '#4545d1',

    // 温暖色阶 (保留用于组件变体)
    warmPrimary: 'hsl(30, 53%, 64%)',      // buff
    warmSecondary: 'hsl(67, 50%, 86%)',    // beige
    warmAccent: 'hsl(43, 82%, 89%)',       // papaya-whip
    warmMuted: 'hsl(74, 32%, 76%)',        // tea-green
    warmBackground: 'hsl(52, 94%, 94%)',   // cornsilk

    // macOS特有颜色
    accent: isDarkMode ? '#ff6f00' : isLightMode ? 'hsl(43, 82%, 79%)' : '#ff9f0a',
    separator: isDarkMode ? '#38383a' : isLightMode ? 'hsl(67, 50%, 80%)' : '#d1d1d6',
  };

  return colors;
}

