{"output":"// 系统主题检测和跟随工具
// 提供系统主题变化的实时监听和管理

export type SystemTheme = 'light' | 'dark';

export interface SystemThemeInfo {
  theme: SystemTheme;
  timestamp: number;
  source: 'initial' | 'media-query' | 'system-preference';
}

class SystemThemeManager {
  private static instance: SystemThemeManager;
  private listeners: Set<(theme: SystemTheme, info: SystemThemeInfo) => void> = new Set();
  private currentTheme: SystemTheme = 'light';
  private mediaQuery: MediaQueryList | null = null;
  private lastChangeTime: number = 0;

  private constructor() {
    this.initialize();
  }

  public static getInstance(): SystemThemeManager {
    if (!SystemThemeManager.instance) {
      SystemThemeManager.instance = new SystemThemeManager();
    }
    return SystemThemeManager.instance;
  }

  private initialize(): void {
    // 检测初始系统主题
    this.currentTheme = this.getSystemTheme();

    // 设置媒体查询监听
    if (typeof window !== 'undefined' && window.matchMedia) {
      this.mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      this.setupMediaQueryListener();
    }

    // 监听系统主题变化（macOS 特有）
    this.setupSystemPreferenceListener();
  }

  private getSystemTheme(): SystemTheme {
    if (typeof window === 'undefined') {
      return 'light';
    }

    // 优先使用 matchMedia API
    if (window.matchMedia) {
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }

    // 回退到时间检测（不太准确但可用）
    const hour = new Date().getHours();
    return (hour >= 18 || hour < 6) ? 'dark' : 'light';
  }

  private setupMediaQueryListener(): void {
    if (!this.mediaQuery) return;

    // 处理兼容性问题
    const mediaQuery = this.mediaQuery;

    if (mediaQuery.addEventListener) {
      // 现代浏览器
      mediaQuery.addEventListener('change', this.handleMediaQueryChange.bind(this));
    } else if (mediaQuery.addListener) {
      // 旧版浏览器兼容
      mediaQuery.addListener(this.handleMediaQueryChange.bind(this));
    }
  }

  private handleMediaQueryChange = (event: MediaQueryListEvent | MediaQueryList): void => {
    const now = Date.now();

    // 防抖处理，避免快速连续变化
    if (now - this.lastChangeTime < 100) {
      return;
    }

    const newTheme = event.matches ? 'dark' : 'light';
    if (newTheme !== this.currentTheme) {
      this.currentTheme = newTheme;
      this.lastChangeTime = now;

      const info: SystemThemeInfo = {
        theme: newTheme,
        timestamp: now,
        source: 'media-query'
      };

      this.notifyListeners(newTheme, info);
    }
  };

  private setupSystemPreferenceListener(): void {
    // 这里可以添加更多系统级的主题检测
