      // Safari/Chrome 可能支持 WebKit 的主题检测
      try {
        // 检测系统主题偏好变化
        const observer = new MutationObserver(() => {
          const newTheme = this.getSystemTheme();
          if (newTheme !== this.currentTheme) {
            this.currentTheme = newTheme;

            const info: SystemThemeInfo = {
              theme: newTheme,
              timestamp: Date.now(),
              source: 'system-preference'
            };

            this.notifyListeners(newTheme, info);
          }
        });

