        console.warn('Failed to setup system preference listener:', error);
      }
    }
  }

  private notifyListeners(theme: SystemTheme, info: SystemThemeInfo): void {
    this.listeners.forEach(listener => {
      try {
        listener(theme, info);
      } catch (error) {
        console.error('Error in system theme listener:', error);
      }
    });
  }

  // 公共 API
  public getCurrentTheme(): SystemTheme {
    return this.currentTheme;
  }

  public addListener(
    listener: (theme: SystemTheme, info: SystemThemeInfo) => void
  ): () => void {
    this.listeners.add(listener);

    // 立即通知当前主题
    const info: SystemThemeInfo = {
      theme: this.currentTheme,
      timestamp: Date.now(),
      source: 'initial'
    };

    try {
      listener(this.currentTheme, info);
    } catch (error) {
      console.error('Error in initial system theme listener:', error);
    }

