// 主题切换动画 Hook
export function useThemeTransition() {
  const { theme, setTheme } = useTheme();
  const [isTransitioning, setIsTransitioning] = useState(false);

  const transitionTheme = useCallback(async (newTheme: Theme) => {
    if (newTheme === theme) return;

    setIsTransitioning(true);

    // 添加过渡动画类
    document.body.classList.add('theme-transitioning');

    // 切换主题
    setTheme(newTheme);

    // 等待动画完成
    await new Promise(resolve => setTimeout(resolve, 300));

    // 移除过渡动画类
    document.body.classList.remove('theme-transitioning');
    setIsTransitioning(false);
  }, [theme, setTheme]);

  return {
    transitionTheme,
    isTransitioning,
  };
}

// 主题预览 Hook
export function useThemePreview() {
  const [previewTheme, setPreviewTheme] = useState<Theme | null>(null);
  const originalTheme = useTheme().theme;

  const startPreview = useCallback((theme: Theme) => {
    setPreviewTheme(theme);
    // 临时应用预览主题
    const root = document.documentElement;
    root.classList.add('theme-preview');

    // 移除所有主题类
    root.classList.remove('dark');

    if (theme === 'dark') {
      root.classList.add('dark');
    } else if (theme === 'light') {
      // light模式不添加类，作为默认（使用温暖配色）
    } else {
      // system theme
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      if (systemPrefersDark) {
        root.classList.add('dark');
      }
      // light模式不需要添加类
    }
  }, []);

  const endPreview = useCallback(() => {
    setPreviewTheme(null);
    const root = document.documentElement;
    root.classList.remove('theme-preview');

    // 恢复原始主题
    root.classList.remove('light', 'warm', 'dark');

    if (originalTheme === 'dark') {
      root.classList.add('dark');
    }
    // light模式不添加类，system theme会由useTheme hook处理
  }, [originalTheme]);

  return {
    previewTheme,
    startPreview,
    endPreview,
  };
